#nullable enable

using System;
using System.IO;
using Campground.Shared.Registry;
using MediaBrowser.Common.Configuration;

namespace Campground.Shared.Storage
{
    /// <summary>
    /// Where Campground keeps shared state: <c>&lt;jellyfin data&gt;/campground</c>. Each plugin's own data goes
    /// in <c>&lt;jellyfin data&gt;/campground/&lt;pluginId&gt;</c>. The first plugin to start sets the root for all.
    /// </summary>
    internal static class CampgroundPaths
    {
        private const string StateSection = "paths";

        /// <summary>Call once at plugin start-up.</summary>
        internal static void Initialize(IApplicationPaths paths) => Initialize(Path.Combine(paths.DataPath, "campground"));

        /// <summary>Sets the root directly (tests, tools).</summary>
        internal static void Initialize(string root)
        {
            CampgroundRegistry.Section(StateSection).TryAdd("root", root);
            Directory.CreateDirectory(Root);
        }

        /// <summary>For tests only: replace the root.</summary>
        internal static void OverrideForTests(string root) => CampgroundRegistry.Section(StateSection)["root"] = root;

        /// <summary>The shared root.</summary>
        internal static string Root =>
            CampgroundRegistry.Section(StateSection).TryGetValue("root", out var r) && r is string s
                ? s
                : throw new InvalidOperationException("CampgroundPaths.Initialize has not been called.");

        /// <summary>True once a root is set.</summary>
        internal static bool IsInitialized => CampgroundRegistry.Section(StateSection).ContainsKey("root");

        /// <summary>A plugin's own folder (created on demand).</summary>
        internal static string ForPlugin(string pluginId)
        {
            if (pluginId.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0 || pluginId.Contains("..", StringComparison.Ordinal))
            {
                throw new ArgumentException("Invalid plugin id.", nameof(pluginId));
            }

            var dir = Path.Combine(Root, pluginId);
            Directory.CreateDirectory(dir);
            return dir;
        }
    }
}
